import type { BrandLogo } from "../icons/brandLogos";

/**
 * The marks the project initializer draws — one per template, plus the runtimes and package managers
 * its environment panel names.
 *
 * **Copied, not fetched**, for the reason `icons/brandLogos.ts` gives: every body below is verbatim
 * from `@iconify-json/logos` (the gilbarbara/logos set, CC0-1.0), the package the file-icon picker
 * already loads, and loading that 7 MB set to paint a 16px glyph is not a trade worth making. This
 * file lives in the initializer's own lazy chunk, so none of it reaches the app's entry bundle.
 *
 * Two marks were near-black on their own (Express's wordmark, Expo's chevron) and would vanish on a
 * dark theme; their fill is `currentColor` here instead, which `BrandGlyph` sets to the text colour.
 * Flask and Rust ship with no fill at all and inherit it the same way. Next.js's disc had no fill
 * either — inherited, it turned the mark into a pale disc under a white "N" — so it is black here,
 * as Next.js draws it.
 *
 * To refresh one: copy `body`, `width` and `height` for the id named in its comment from
 * `node_modules/@iconify-json/logos/icons.json` (both default to 256 when the icon omits them).
 */
